import "server-only";
import { createHash } from "node:crypto";
import fs from "node:fs";
import path from "node:path";

// Generated by generate-blocklist.mjs from the pinned SecLists NCSC list (see that file).
// The checksum covers the LF form, because Windows checkouts may convert line endings.
export const BLOCKLIST_PATH = path.join(process.cwd(), "src", "server", "auth", "password-blocklist.txt");
export const BLOCKLIST_SHA256 = "a6471a421ad7ae986034698a9135e48236ae918ce595a91e33375ee43dc0189d";

export class BlocklistUnavailableError extends Error {
  constructor(reason: string) { super(`Password blocklist unavailable: ${reason}`); }
}

const loaded = new Map<string, ReadonlySet<string>>();

// Every password set path calls this before hashing; any failure stops the write.
export function loadPasswordBlocklist(file = BLOCKLIST_PATH, expectedSha256 = BLOCKLIST_SHA256): (form: string) => boolean {
  let entries = loaded.get(file);
  if (!entries) {
    let text: string;
    try { text = fs.readFileSync(file, "utf8").replace(/\r\n/g, "\n"); } catch { throw new BlocklistUnavailableError("missing"); }
    if (createHash("sha256").update(text, "utf8").digest("hex") !== expectedSha256) throw new BlocklistUnavailableError("checksum mismatch");
    entries = new Set(text.split("\n").filter(Boolean));
    if (entries.size === 0) throw new BlocklistUnavailableError("empty");
    loaded.set(file, entries);
  }
  const set = entries;
  return (form) => set.has(form);
}
